// Telangana SCERT Class 10 — Hindi (Second Language), 12 lessons. Original teaching aligned to the official
// chapter list (src/content/ts/books.ts, syllabus.json). Lesson texts are NOT reproduced: every सारांश (summary)
// is written afresh, and at most one short line of a classical (public-domain) poem is quoted for analysis.
// Teaching text is Devanagari Hindi kept in the `en` field (so it always shows) with short English glosses in
// brackets for learners whose first language is Telugu.
import { tp, ex, p, h, tip, def, keys, remember, photo, stepsB, choose, matching, ordering, tapAll, type USpec, type TSpec } from '../../lib/kit';
import { tsSrc } from '../books';

const src = (n: number) => tsSrc(10, 'hindi', n);

// ---------- compact practice factories ----------
/** [प्रश्न, सही उत्तर, गलत विकल्प, संकेत (hint), कारण (why)] */
type MQ = [q: string, a: string, w: string[], hint: string, why: string];
const mcq = (key: string, hint0: string, bank: MQ[], d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const [q, a, w, h1, why] = r.pick(bank);
  return {
    type: 'mcq', prompt: q, ...choose(r, a, w), hints: [hint0, h1],
    mistakes: [{ when: 'wrong', explain: `अभी सही नहीं (Not quite). ${why}` }],
    solution: [`सही उत्तर (Answer): ${a}`, why],
  };
}, d);

const matchT = (key: string, what: string, pool: [string, string][], hints: string[], n = 4, d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const pairs = r.shuffle(pool).slice(0, n);
  const m = matching(r, pairs);
  return {
    type: 'match', prompt: `मिलान कीजिए (Match) — ${what}: ${pairs.map((x) => x[0]).join(' · ')}`, left: m.left, right: m.right, answer: m.answer,
    hints, mistakes: [{ when: 'wrong', explain: 'कम से कम एक जोड़ी गलत है। बाईं ओर के हर शब्द को एक-एक करके जाँचिए। (At least one pair is wrong — check each one.)' }],
    solution: pairs.map(([a, b]) => `${a} → ${b}`),
  };
}, d);

const orderT = (key: string, prompt: string, steps: string[], hints: string[], why: string, d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => ({
  type: 'order', prompt, ...ordering(r, steps), hints,
  mistakes: [{ when: 'wrong', explain: `क्रम अभी सही नहीं है (Order not right yet). ${why}` }],
  solution: [...steps.map((s, i) => `${i + 1}. ${s}`), why],
}), d);

const tapT = (key: string, prompt: string, pool: [string, boolean][], hints: string[], why: string, n = 5, d: 1 | 2 | 3 = 1): TSpec => tp(key, (r) => {
  const pick = r.shuffle(pool).slice(0, n);
  const yes = pool.find((x) => x[1])!, no = pool.find((x) => !x[1])!;
  if (!pick.some((x) => x[1])) pick[0] = yes;
  if (!pick.some((x) => !x[1])) pick[n - 1] = no;
  return {
    type: 'tap', prompt, ...tapAll(r, pick.map(([label, ok]) => ({ label, ok }))), hints,
    mistakes: [{ when: 'wrong', explain: `हर विकल्प को अलग-अलग जाँचिए (Check each option separately). ${why}` }],
    solution: [`सही विकल्प (Correct): ${pick.filter((x) => x[1]).map((x) => x[0]).join(', ')}`, why],
  };
}, d);

